// docs/DATA-QUALITY.md, generated by build.js from data/drugs.json (schema openbill.drugs/3).
//
// Everything here is computed from the doc with the same core code the page runs: the rows are
// linked (linkRows), grouped into products (groupProducts) and summarized (summarizeProduct),
// so the reference prices and spreads counted below are the ones a card shows. No clock is
// read: every age is measured against the source's own retrieved_date, so the same doc always
// gives the same bytes.

import { PRICE_STATES, validateRecord } from '../core/provenance.js';
import { SOURCE_INFO, NADAC_EXPLANATION_CODES, NADAC_CARRIED_FORWARD_CODES } from '../core/sources.js';
import { summarizeProduct, defaultQuantity, freshness, distinctLabelers, EXTREME_HIGH, EXTREME_LOW, EXTREME_HEADLINE, isExtremeSpread } from '../core/rules.js';
import { epcClasses } from '../core/related.js';
import { linkRows } from '../core/pack.js';
import { groupProducts } from '../core/search.js';
import { formatCount, formatMultiple, formatUnitPrice, divideMoney, multiplyDecimal, decimalString } from '../core/money.js';
import { formatNdc, isNdc11 } from '../core/ndc.js';

/** Floor: at least this percentage of rows must be `filed` (brief, "Testing"). */
export const FLOOR_FILED_PERCENT = 70;

/** How many products each outlier list shows. */
export const EXTREME_LIST_LENGTH = 10;

/** Characters of a sha256 shown in tables. */
export const SHA_PREFIX = 12;

/**
 * Why a row has no Part D figure, keyed by the reason codes tools/build_drugs.py counts in
 * counts.part_d_unmatched. Wording follows PART_D_UNMATCHED in tools/build_drugs.py.
 * @type {Readonly<Record<string, string>>}
 */
export const PART_D_UNMATCHED_REASONS = Object.freeze({
  release_form_conflict: 'FDA’s dosage form or name states a release form (extended or delayed release) the NADAC description does not, or the reverse',
  ambiguous_name: 'more than one Part D row carries this product name and release form',
  generic_name_disagrees: 'a Part D row has this name but its generic name disagrees with FDA’s nonproprietary name',
  otc_no_exact_name: 'OTC product with no Part D row of exactly this name (Part D excludes OTC drugs)',
  otc_monograph: 'OTC product sold under an FDA OTC monograph; Part D excludes OTC drugs, so a Part D row of this name is a different product',
  otc_generic_name: 'OTC product whose name matches only a Part D row named by the generic name, which is the prescription product (Part D excludes OTC drugs)',
  ambiguous_presentation: 'Part D lists presentations of this name separately (for example vial and pen) and the NADAC description does not settle which one this NDC is',
  ambiguous_salt: 'Part D has rows for this substance under different salts (for example Buprenorphine and Buprenorphine HCl) and neither the NADAC description nor FDA’s nonproprietary name settles which',
  no_brand_name: 'brand product with no Part D row of this brand name and release form',
  ambiguous_generic: 'more than one Part D generic row could match',
  no_generic_name: 'no Part D row with this generic name and release form',
  no_value: 'the matched Part D row has no average spending per dosage unit for the data year',
  mixed_units: 'NADAC prices the NDCs joined to this Part D name in more than one unit and this NDC’s unit is not the one nearly all of them share, so CMS’s average per dosage unit is not in this NDC’s unit',
  multi_route_no_identity: 'the Part D name carries CMS’s * (an average over several routes of administration) and this NDC has no FDA identity with a route, and no accepted FDA product record for its product code with one, so its route is unknown',
  multi_route_minority: 'the Part D name carries CMS’s * (an average over several routes of administration) and this NDC’s FDA route is not the one most NDCs joined to the name share',
  multi_route_tie: 'the Part D name carries CMS’s * (an average over several routes of administration) and the NDCs joined to it split evenly between routes, so no route is shared by most of them',
});

/**
 * Why a row has no Part B data, keyed by the reason codes tools/build_drugs.py counts in
 * counts.part_b_unmatched (PartB.block in tools/build_drugs.py).
 * @type {Readonly<Record<string, string>>}
 */
export const PART_B_UNMATCHED_REASONS = Object.freeze({
  not_in_crosswalk: 'the NDC is not on the current quarter’s NDC-HCPCS crosswalk (most drugs filled at a pharmacy are not billed to Part B)',
  ambiguous_crosswalk: 'the NDC is on more than one crosswalk line, and the lines disagree on the HCPCS code or the package figures',
  hcpcs_not_in_limits: 'the crosswalk’s HCPCS code is not in the payment limit file',
  hcpcs_repeated_in_limits: 'the payment limit file lists the HCPCS code more than once',
  limit_not_a_positive_number: 'the payment limit for the code is blank, N/A or not a positive number',
  blank_package_or_coinsurance: 'the crosswalk’s package size, package quantity or billable units, or the file’s coinsurance percentage, is blank or not a number',
});

/** Why a row's Part D figure is or is not usable as its reference (mirrors referencePrice). */
const PART_D_SIDE = Object.freeze({
  usable: 'usable',
  no_match: 'no Part D name matched',
  outlier: 'Part D figure flagged as an outlier by CMS',
  no_value: 'matched Part D row has no usable average',
  unit: 'Part D average is per a different unit',
});

/** Why a row's Part B figure is or is not usable as its reference (mirrors partBPerNadacUnit). */
const PART_B_SIDE = Object.freeze({
  not_on_crosswalk: 'NDC not on the Part B crosswalk',
  unit_not_reconciled: 'package unit not reconciled to the NADAC unit',
  other: 'Part B inputs not usable',
});

const KIND_LABEL = Object.freeze({ part_d: 'Medicare Part D', part_b: 'Medicare Part B' });

/** counts.part_d_by_basis keys: how CMS names the matched Part D row. */
const BASIS_LABEL = Object.freeze({ brand: 'a trade name', generic: 'the generic name' });

/** counts.part_d_by_join keys: which step of the name join matched. */
const JOIN_LABEL = Object.freeze({ name: 'by exact product name', generic_name: 'by generic name' });

/**
 * counts.part_b_unit_reconciled_by keys: how the crosswalk's package size was reconciled to the
 * NADAC unit (PartB.block in tools/build_drugs.py).
 * @type {Readonly<Record<string, string>>}
 */
export const PART_B_RECONCILED_BY = Object.freeze({
  fda_amount: 'FDA’s package description gives the same total as the crosswalk',
  kit: 'the NDC is a kit NADAC prices per EA, so the count is of whole kits',
  strength_check: 'the crosswalk’s billing-unit columns disagree and FDA’s strength × amount ÷ the HCPCS dosage settles them exactly',
});

/** Why a row with a Part D match still uses Part B (keys of PART_D_SIDE). */
const FALLBACK_PHRASE = Object.freeze({
  outlier: 'CMS flags the Part D figure as an outlier',
  no_value: 'the matched Part D row has no usable average',
  unit: 'the Part D average is per a different unit',
});

const AGE_FROM_LABEL = Object.freeze({
  as_of_date: 'the file date',
  period_start: 'the start of the quarter',
  period_end: 'the end of the data year',
});

const HTTPS_URL_RE = /^https:\/\/[^\s/]+\.[^\s]*$/;
const METHODOLOGY_URL_RE = /^methodology\.html#[a-z0-9][a-z0-9-]*$/;

function cmp(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

/**
 * a as a percentage of b, rounded half-up to one decimal, e.g. "90.2%"; "n/a" when b is 0.
 * A share above 0 that rounds to 0.0% is "<0.1%", so a real count never reads as none.
 * @param {number} a
 * @param {number} b
 * @returns {string}
 */
export function pct(a, b) {
  if (!Number.isFinite(a) || !Number.isFinite(b)) throw new TypeError(`pct needs two numbers, got ${a} and ${b}`);
  if (b === 0) return 'n/a';
  const v = divideMoney(multiplyDecimal(a, 100), b, 1);
  if (v === 0 && a > 0) return '<0.1%';
  const s = decimalString(v);
  return `${s.includes('.') ? s : s + '.0'}%`;
}

/**
 * "1 day", "3 days", "1,461 names": a count with its noun, singular for exactly 1. A count
 * the doc does not have reads "an unrecorded number of days", never 0.
 * @param {*} n
 * @param {string} one
 * @param {string} [many]
 * @returns {string}
 */
export function plural(n, one, many = `${one}s`) {
  if (!(typeof n === 'number' && Number.isFinite(n))) return `an unrecorded number of ${many}`;
  return `${formatCount(n)} ${n === 1 ? one : many}`;
}

/**
 * A count for display ("30,031"), or "not recorded" when the doc does not have it. A missing
 * count is never shown as 0.
 * @param {*} n
 * @returns {string}
 */
export function countText(n) {
  return typeof n === 'number' && Number.isFinite(n) ? formatCount(n) : 'not recorded';
}

function isRecordLike(v) {
  return isPlainObject(v) && (hasOwn(v, 'value') || hasOwn(v, 'kind') || hasOwn(v, 'state'));
}

function walkRecords(value, path, out) {
  if (Array.isArray(value)) {
    value.forEach((v, i) => walkRecords(v, `${path}[${i}]`, out));
    return;
  }
  if (!isPlainObject(value)) return;
  if (isRecordLike(value)) {
    out.push({ path, record: value });
    return;
  }
  for (const k of Object.keys(value)) walkRecords(value[k], `${path}.${k}`, out);
}

/**
 * Every price record in a drugs doc, each once: the records on the rows and in the shared
 * part_d_names and part_b_codes tables (a table record is counted once, however many rows
 * point at it). A record is any object with a `value`, `kind` or `state` field, so a record
 * missing some of its fields is still found (and fails validateRecord). `path` says where it
 * is, e.g. `rows[ndc 00003089421].nadac` or `part_b_codes["J0129"].payment_limit`.
 * @param {object} doc
 * @returns {{ path: string, record: object }[]}
 */
export function collectRecords(doc) {
  const out = [];
  (Array.isArray(doc.rows) ? doc.rows : []).forEach((row, i) => {
    const label = isPlainObject(row) && typeof row.ndc === 'string' ? `rows[ndc ${row.ndc}]` : `rows[${i}]`;
    if (isPlainObject(row)) for (const k of Object.keys(row)) walkRecords(row[k], `${label}.${k}`, out);
  });
  for (const table of ['part_d_names', 'part_b_codes']) {
    const t = doc[table];
    if (!isPlainObject(t)) continue;
    for (const key of Object.keys(t)) walkRecords(t[key], `${table}[${JSON.stringify(key)}]`, out);
  }
  return out;
}

function hasSourceUrl(rec) {
  const u = rec && rec.source_url;
  return typeof u === 'string' && ((HTTPS_URL_RE.test(u) && !/\s/.test(u)) || METHODOLOGY_URL_RE.test(u));
}

function usableUsd(rec) {
  return Boolean(rec) && validateRecord(rec).length === 0 && rec.kind === 'usd';
}

function partDSide(row) {
  const pd = row.part_d;
  if (!pd) return 'no_match';
  if (pd.outlier === true) return 'outlier';
  if (!usableUsd(pd.avg_per_unit)) return 'no_value';
  if (pd.avg_per_unit.per !== row.unit) return 'unit';
  return 'usable';
}

// For a row with no reference price: why its Part B figure is not usable.
function partBSide(row) {
  const pb = row.part_b;
  if (!pb) return 'not_on_crosswalk';
  if (pb.package_unit === null || pb.package_unit === undefined) return 'unit_not_reconciled';
  return 'other';
}

// The page's own test (rules.js), so the counts here are the cards that take the extreme headline.
function isExtreme(spreadRecord) {
  return isExtremeSpread(spreadRecord);
}

function bump(map, key, n = 1) {
  map[key] = (map[key] || 0) + n;
}

function byState(records) {
  const out = {};
  for (const s of PRICE_STATES) out[s] = 0;
  for (const r of records) bump(out, typeof r.state === 'string' ? r.state : String(r.state));
  return out;
}

const CACHE = new WeakMap();

/**
 * Everything DATA-QUALITY.md and methodology.html report about a doc, computed once per doc
 * object (cached; treat the result as read-only). Throws if the doc is not schema
 * openbill.drugs/3 (linkRows), or if a reference price disagrees with the field-level reason
 * this module gives for it (a bug, which must not be published as a statistic).
 * @param {object} doc parsed data/drugs.json
 * @returns {object}
 */
export function analyzeDoc(doc) {
  if (!isPlainObject(doc)) throw new TypeError('analyzeDoc needs the parsed data/drugs.json');
  const cached = CACHE.get(doc);
  if (cached) return cached;

  const rows = doc.rows;
  const counts = isPlainObject(doc.counts) ? doc.counts : {};
  const sources = isPlainObject(doc.sources) ? doc.sources : {};
  const names = isPlainObject(doc.part_d_names) ? doc.part_d_names : {};
  const codes = isPlainObject(doc.part_b_codes) ? doc.part_b_codes : {};

  const linked = linkRows(doc);
  const products = groupProducts(linked);

  // Records.
  const records = collectRecords(doc);
  const problems = [];
  for (const { path, record } of records) {
    const p = validateRecord(record);
    if (p.length) problems.push({ path, problems: p });
  }
  const usd = records.filter((x) => x.record.kind === 'usd');
  const usdNotPositive = usd.filter((x) => !(typeof x.record.value === 'number' && x.record.value > 0));
  const withoutUrl = records.filter((x) => !hasSourceUrl(x.record));

  // Rows.
  const rowState = byState(rows.map((r) => (r && r.nadac ? r.nadac : { state: 'missing' })));
  const ndcs = rows.map((r) => r.ndc);
  const repeatedNdcs = ndcs.length - new Set(ndcs).size;

  // References and spreads, through summarizeProduct: the page's own code path.
  const refRows = { part_d: 0, part_b: 0, none: 0 };
  const refProducts = { part_d: 0, part_b: 0, none: 0 };
  const spreads = { part_d: byState([]), part_b: byState([]) };
  const altSpreads = byState([]);
  const extremeRows = { part_d: 0, part_b: 0 };
  const extremeProducts = new Set();
  const noneWhy = {};
  const partBFallback = {}; // Part B is the reference although the row has a Part D match
  let alternates = 0;
  const extremes = [];
  // The cost-plus estimate at each product's starting quantity, as a card first shows it.
  const costPlus = { products: 0, missing: {} };
  for (const p of products) {
    // A pack total needs valid NADAC records; a doc that breaks that is reported by the floors
    // below, so it is summarized without a quantity rather than stopping the report.
    const nadacValid = p.rows.every((r) => r && r.nadac && validateRecord(r.nadac).length === 0);
    const s = nadacValid ? summarizeProduct(p.rows, defaultQuantity(p.rows).qty) : summarizeProduct(p.rows);
    if (!nadacValid) bump(costPlus.missing, 'A NADAC record of this product is not valid, so there is no pack total to estimate from.');
    else if (s.cost_plus.missing) bump(costPlus.missing, s.cost_plus.reason);
    else costPlus.products += 1;
    bump(refProducts, s.reference.missing ? 'none' : s.reference.kind);
    let hi = null;
    let lo = null;
    for (const x of s.per_ndc) {
      const ref = x.reference;
      const dSide = partDSide(x.row);
      if (ref.missing) {
        refRows.none += 1;
        const bSide = partBSide(x.row);
        if (dSide === 'usable') throw new Error(`quality: NDC ${x.ndc} has a usable Part D figure but no reference price`);
        bump(noneWhy, `${dSide}|${bSide}`);
      } else {
        refRows[ref.kind] += 1;
        if (ref.kind === 'part_d' && dSide !== 'usable') throw new Error(`quality: NDC ${x.ndc} uses Part D although its Part D figure is ${dSide}`);
        if (ref.kind === 'part_b') {
          if (dSide === 'usable') throw new Error(`quality: NDC ${x.ndc} uses Part B although its Part D figure is usable`);
          if (dSide !== 'no_match') bump(partBFallback, dSide);
        }
        if (ref.alternate) alternates += 1;
      }
      if (!x.spread.missing) {
        const rec = x.spread.record;
        bump(spreads[x.spread.kind], rec.state);
        if (isExtreme(rec)) {
          extremeRows[x.spread.kind] += 1;
          extremeProducts.add(p.name);
        }
        if (!hi || rec.value > hi.spread.record.value) hi = x;
        if (!lo || rec.value < lo.spread.record.value) lo = x;
      }
      if (x.alternate_spread && !x.alternate_spread.missing) bump(altSpreads, x.alternate_spread.record.state);
    }
    if (hi) extremes.push({ product: p.name, hi, lo, ndcs: s.per_ndc.filter((x) => !x.spread.missing).length });
  }
  const spreadEntry = (e, x) => ({
    product: e.product,
    ndc: x.ndc,
    ndcs: e.ndcs,
    kind: x.spread.kind,
    nadac: x.nadac,
    reference: x.spread.reference,
    spread: x.spread.record,
  });
  const highest = [...extremes]
    .sort((a, b) => b.hi.spread.record.value - a.hi.spread.record.value || cmp(a.product, b.product))
    .slice(0, EXTREME_LIST_LENGTH)
    .map((e) => spreadEntry(e, e.hi));
  const lowest = [...extremes]
    .sort((a, b) => a.lo.spread.record.value - b.lo.spread.record.value || cmp(a.product, b.product))
    .slice(0, EXTREME_LIST_LENGTH)
    .map((e) => spreadEntry(e, e.lo));

  // Part D outliers (the CMS flag), by name and by the rows pointing at the name.
  const nameList = Object.values(names);
  const outlierNames = nameList.filter((n) => n.outlier === true).length;
  const blankFlagNames = nameList.filter((n) => n.outlier === null).length;
  const outlierRows = linked.filter((r) => r.part_d && r.part_d.outlier === true).length;
  const blankFlagRows = linked.filter((r) => r.part_d && r.part_d.outlier === null).length;
  const multiRouteNames = nameList.filter((n) => typeof n.brand_name === 'string' && n.brand_name.includes('*')).length;
  const multiRouteRows = linked.filter((r) => r.part_d && typeof r.part_d.brand_name === 'string' && r.part_d.brand_name.includes('*')).length;

  // Part B labelers: one labeler is what lets a Part B spread be derived.
  const codeList = Object.values(codes);
  // The builder counts distinct labeler names (counts.part_b_single_labeler_codes). The page counts
  // companies, folding spellings with distinctLabelers() (review PARTB-8), and so does the prose.
  const companies = (ls) => (Array.isArray(ls) ? distinctLabelers(ls).length : null);
  const singleNameCodes = codeList.filter((c) => Array.isArray(c.labelers) && c.labelers.length === 1).length;
  const singleLabelerCodes = codeList.filter((c) => companies(c.labelers) === 1).length;
  const singleLabelerRows = linked.filter((r) => r.part_b && companies(r.part_b.labelers) === 1);
  const labelerVariants = Object.keys(codes)
    .sort(cmp)
    .map((code) => {
      const ls = Array.isArray(codes[code].labelers) ? codes[code].labelers : [];
      return { code, listed: ls.length, distinct: companies(ls) };
    })
    .filter((x) => x.distinct < x.listed);

  // NADAC explanation codes and carried-forward rows.
  const explanation = {};
  const carriedByCodes = {};
  for (const r of rows) {
    for (const c of r.explanation_codes || []) bump(explanation, c);
    if (r.carried_forward) bump(carriedByCodes, (r.explanation_codes || []).join(', ') || 'none');
  }
  const carriedRows = rows.filter((r) => r.carried_forward);
  const carriedProducts = new Set(carriedRows.map((r) => r.name)).size;
  const effective = rows.map((r) => r.nadac && r.nadac.effective_date).filter((d) => typeof d === 'string').sort(cmp);

  // Source ages at retrieval: no clock, so each age is measured to the source's retrieved_date.
  const sourceIds = Object.keys(sources);
  const ages = sourceIds.map((id) => {
    const entry = sources[id];
    const info = SOURCE_INFO[id];
    if (!info) return { id, info: null, fresh: null };
    const fresh = typeof entry.retrieved_date === 'string' ? freshness(entry, info, entry.retrieved_date) : null;
    return { id, info, fresh };
  });

  const identity = linked.filter((r) => r.identity).length;

  // FDA pharmacologic classes (identity.pharm_classes): the [EPC] entries feed the class pages.
  const isEpc = (e) => typeof e === 'string' && /\s\[EPC\]$/.test(e);
  const classRows = linked.filter((r) => r.identity && Array.isArray(r.identity.pharm_classes));
  const epcKeys = new Set(classRows.flatMap((r) => r.identity.pharm_classes.filter(isEpc)));
  const pharmClasses = Object.freeze({
    rows: classRows.length,
    epcRows: classRows.filter((r) => r.identity.pharm_classes.some(isEpc)).length,
    epcClasses: epcKeys.size,
    productsWithEpc: products.filter((p) => epcClasses(p).length > 0).length,
  });
  const partD = linked.filter((r) => r.part_d).length;
  const partB = linked.filter((r) => r.part_b).length;
  const partBReconciled = linked.filter((r) => r.part_b && r.part_b.package_unit !== null && r.part_b.package_unit !== undefined).length;

  const recomputed = {
    rows: rows.length,
    distinct_names: products.length,
    identity_matched: identity,
    part_d_matched: partD,
    part_b_matched: partB,
    part_b_unit_reconciled: partBReconciled,
    part_d_names: nameList.length,
    part_b_codes: codeList.length,
    part_b_single_labeler_codes: singleNameCodes,
    part_d_outliers: outlierRows,
    part_d_outlier_flag_blank: blankFlagRows,
    part_d_multiple_routes: multiRouteRows,
    carried_forward: carriedRows.length,
    with_generic_nadac: rows.filter((r) => r.generic_nadac).length,
  };
  const recordsByState = byState(records.map((x) => x.record));
  const mismatches = [];
  for (const [k, v] of Object.entries(recomputed)) {
    if (counts[k] !== v) mismatches.push({ key: k, builder: counts[k], recomputed: v });
  }
  const sameMap = (a, b) => {
    const keys = new Set([...Object.keys(a || {}), ...Object.keys(b || {})]);
    return [...keys].every((k) => ((a || {})[k] || 0) === ((b || {})[k] || 0));
  };
  // Counts the builder added with identity.pharm_classes; older docs (and the fixture) may lack them.
  for (const [k, v] of [
    ['identity_with_pharm_classes', pharmClasses.rows],
    ['epc_classes', pharmClasses.epcClasses],
  ]) {
    if (hasOwn(counts, k) && counts[k] !== v) mismatches.push({ key: k, builder: counts[k], recomputed: v });
  }
  if (!sameMap(counts.rows_by_state, rowState)) mismatches.push({ key: 'rows_by_state', builder: counts.rows_by_state, recomputed: rowState });
  if (!sameMap(counts.records_by_state, recordsByState)) {
    mismatches.push({ key: 'records_by_state', builder: counts.records_by_state, recomputed: recordsByState });
  }
  // The builder's breakdown of how each package unit was reconciled must add up to the rows that are.
  if (hasOwn(counts, 'part_b_unit_reconciled_by') && sumValues(counts.part_b_unit_reconciled_by) !== partBReconciled) {
    mismatches.push({ key: 'part_b_unit_reconciled_by (sum)', builder: sumValues(counts.part_b_unit_reconciled_by), recomputed: partBReconciled });
  }

  const analysis = Object.freeze({
    rows: rows.length,
    products: products.length,
    productList: products, // groupProducts(linkRows(doc)): linked, shared with the doc; read-only
    rowState,
    records: records.length,
    recordsByState,
    recordProblems: problems,
    usdRecords: usd.length,
    usdNotPositive,
    withoutUrl,
    repeatedNdcs,
    identity,
    pharmClasses,
    costPlus,
    partD,
    partB,
    partBReconciled,
    partDNames: nameList.length,
    partBCodes: codeList.length,
    outlierNames,
    outlierRows,
    blankFlagNames,
    blankFlagRows,
    multiRouteNames,
    multiRouteRows,
    singleLabelerCodes,
    singleLabelerRows: singleLabelerRows.length,
    singleLabelerReconciledRows: singleLabelerRows.filter((r) => r.part_b.package_unit !== null && r.part_b.package_unit !== undefined).length,
    labelerVariants,
    refRows,
    refProducts,
    alternates,
    partBFallback,
    noneWhy,
    spreads,
    altSpreads,
    extremeRows,
    extremeProducts: extremeProducts.size,
    highest,
    lowest,
    explanation,
    carriedRows: carriedRows.length,
    carriedProducts,
    carriedByCodes,
    effectiveMin: effective[0] || null,
    effectiveMax: effective[effective.length - 1] || null,
    ages,
    sourceIds,
    mismatches,
    floors: floorsOf(doc, { rows: rows.length, rowState, records, usd, usdNotPositive, withoutUrl }),
  });
  CACHE.set(doc, analysis);
  return analysis;
}

function floorsOf(doc, a) {
  const filed = a.rowState.filed || 0;
  const sources = isPlainObject(doc.sources) ? doc.sources : {};
  const ids = Object.keys(sources);
  const badSources = ids.filter((id) => {
    const u = sources[id] && sources[id].source_url;
    return !(typeof u === 'string' && HTTPS_URL_RE.test(u) && !/\s/.test(u));
  });
  const noSources = ids.length === 0;
  const firstPaths = (list) => list.slice(0, 5).map((x) => x.path).join(', ');
  return Object.freeze([
    Object.freeze({
      id: 'rows-filed',
      label: `At least ${FLOOR_FILED_PERCENT}% of rows are filed`,
      pass: a.rows > 0 && filed * 100 >= FLOOR_FILED_PERCENT * a.rows,
      detail: `${formatCount(filed)} of ${formatCount(a.rows)} rows (${pct(filed, a.rows)}) are filed; the floor is ${FLOOR_FILED_PERCENT}%.`,
    }),
    Object.freeze({
      id: 'source-urls',
      label: 'Every source has an https source_url',
      pass: !noSources && badSources.length === 0,
      detail: noSources
        ? 'The doc lists no sources.'
        : badSources.length === 0
        ? `All ${formatCount(ids.length)} sources have one.`
        : `${formatCount(badSources.length)} of ${formatCount(ids.length)} sources do not: ${badSources.join(', ')}.`,
    }),
    Object.freeze({
      id: 'record-urls',
      label: 'Every record has a source_url',
      pass: a.records.length > 0 && a.withoutUrl.length === 0,
      detail:
        a.withoutUrl.length === 0
          ? `All ${formatCount(a.records.length)} records have an https:// or methodology.html# source_url.`
          : `${formatCount(a.withoutUrl.length)} of ${formatCount(a.records.length)} records do not, e.g. ${firstPaths(a.withoutUrl)}.`,
    }),
    Object.freeze({
      id: 'usd-positive',
      label: 'No usd record is 0 or less',
      pass: a.usdNotPositive.length === 0,
      detail:
        a.usdNotPositive.length === 0
          ? `All ${formatCount(a.usd.length)} usd records are above 0.`
          : `${formatCount(a.usdNotPositive.length)} of ${formatCount(a.usd.length)} usd records are 0, negative or not a number, e.g. ${firstPaths(a.usdNotPositive)}.`,
    }),
  ]);
}

/**
 * The quality floors CI holds, each { id, label, pass, detail } with the numbers in `detail`.
 * @param {object} doc
 * @returns {readonly { id: string, label: string, pass: boolean, detail: string }[]}
 */
export function checkFloors(doc) {
  return analyzeDoc(doc).floors;
}

// ---------------------------------------------------------------- markdown

/** Escape text for a markdown paragraph or table cell. */
function md(value) {
  return String(value)
    .replace(/[\\`*_[\]<>|~]/g, (c) => `\\${c}`)
    .replace(/&(?=#?[A-Za-z0-9]+;)/g, '&amp;')
    .replace(/\r?\n/g, ' ');
}

/** A code span, or escaped text when the value could break one. */
function code(value) {
  const s = String(value);
  return /[`|\r\n]/.test(s) || s === '' ? md(s) : `\`${s}\``;
}

function table(head, rows) {
  const line = (cells) => `| ${cells.join(' | ')} |`;
  return [line(head), line(head.map(() => '---')), ...rows.map(line)].join('\n');
}

function ndcText(ndc) {
  return isNdc11(ndc) ? formatNdc(ndc) : String(ndc);
}

function usdText(rec) {
  return `${formatUnitPrice(rec.value)}${rec.per ? ` per ${rec.per}` : ''}`;
}

function stateCounts(map) {
  return PRICE_STATES.map((s) => `${s} ${formatCount(map[s] || 0)}`)
    .concat(Object.keys(map).filter((k) => !PRICE_STATES.includes(k)).map((k) => `${k} ${formatCount(map[k])} (not a price state)`))
    .join(', ');
}

function sortedReasons(map) {
  return Object.entries(isPlainObject(map) ? map : {}).sort((a, b) => b[1] - a[1] || cmp(a[0], b[0]));
}

function sumValues(map) {
  return Object.values(isPlainObject(map) ? map : {}).reduce((a, n) => a + (Number.isFinite(n) ? n : 0), 0);
}

function reasonTable(map, descriptions, total) {
  const entries = sortedReasons(map);
  if (entries.length === 0) return 'None recorded.';
  return table(
    ['reason', 'rows', 'share of all rows', 'what it means'],
    entries.map(([k, n]) => [
      code(k),
      countText(n),
      Number.isFinite(n) ? pct(n, total) : 'n/a',
      hasOwn(descriptions, k) ? md(descriptions[k]) : '**No description yet**: add it to src/build/quality.js.',
    ]),
  );
}

/**
 * docs/DATA-QUALITY.md for a drugs doc: summary, source coverage, reference coverage,
 * unmatched reasons, dates and ages, carried-forward rows, outliers, rejected rows and the
 * floors, with PASS or FAIL. Deterministic: no clock, LF line ends, ends with a newline.
 * @param {object} doc parsed data/drugs.json
 * @returns {string}
 */
export function renderDataQuality(doc) {
  const a = analyzeDoc(doc);
  const c = isPlainObject(doc.counts) ? doc.counts : {};
  const src = isPlainObject(doc.sources) ? doc.sources : {};
  const n = a.rows;
  const nadac = src.nadac || {};
  const out = [];
  const add = (...parts) => out.push(...parts);

  add(
    '<!-- generated by build.js from data/drugs.json — do not edit -->',
    '',
    '# Data quality',
    '',
    `Generated by \`build.js\` (\`src/build/quality.js\`) from \`data/drugs.json\`, schema ${code(doc.schema)}, ` +
      `built from the NADAC file as of ${md(nadac.as_of_date || 'an unknown date')}. Do not edit it by hand: run \`node build.js\`.`,
    '',
    'The figures are recomputed from the rows and tables of `data/drugs.json`, and reference prices and spreads with ' +
      '`summarizeProduct()` from `src/core/rules.js`, the code the page runs. The exceptions are the unmatched reasons, the ' +
      'Part D counts by rate class and the rejected and duplicate lines: the rows do not carry those, so they are the counts ' +
      '`tools/build_drugs.py` records in `counts`. How the joins and rules work: [methodology.html](../methodology.html). The ' +
      'sources and their terms: [DATA_SOURCES.md](DATA_SOURCES.md).',
    '',
    '- [Summary](#summary)',
    '- [Source coverage](#source-coverage)',
    '- [Reference coverage](#reference-coverage)',
    '- [Unmatched reasons](#unmatched-reasons)',
    '- [Dates](#dates)',
    '- [Carried-forward NADAC rows](#carried-forward-nadac-rows)',
    '- [Outliers](#outliers)',
    '- [Rejected and duplicate rows](#rejected-and-duplicate-rows)',
    '- [Floors](#floors)',
    '',
  );

  // Summary.
  add(
    '## Summary',
    '',
    table(
      ['measure', 'value'],
      [
        ['rows (one per NDC in the newest NADAC week)', formatCount(n)],
        ['products (rows grouped by NADAC description)', formatCount(a.products)],
        ['records (each shared table record counted once)', formatCount(a.records)],
        ['records by state', stateCounts(a.recordsByState)],
        ['rows by state (the state of the row’s NADAC price)', stateCounts(a.rowState)],
        ['records failing `validateRecord()`', formatCount(a.recordProblems.length)],
        ['Part D names in `part_d_names`', formatCount(a.partDNames)],
        ['HCPCS codes in `part_b_codes`', formatCount(a.partBCodes)],
        ['brand rows that also carry their generic’s NADAC', countText(c.with_generic_nadac)],
      ],
    ),
    '',
  );
  if (a.mismatches.length === 0) {
    add('These figures match `counts` in `data/drugs.json`.', '');
  } else {
    add(
      '**These recomputed figures disagree with `counts` in `data/drugs.json`:**',
      '',
      table(
        ['count', 'builder', 'recomputed'],
        a.mismatches.map((m) => [code(m.key), md(JSON.stringify(m.builder) ?? 'not recorded'), md(JSON.stringify(m.recomputed))]),
      ),
      '',
    );
  }
  if (a.recordProblems.length) {
    add(
      '**Records that fail `validateRecord()`** (first 20):',
      '',
      ...a.recordProblems.slice(0, 20).map((p) => `- ${code(p.path)}: ${md(p.problems.join('; '))}`),
      '',
    );
  }

  // Source coverage.
  const rateClasses = isPlainObject(c.part_d_by_rate_class) ? c.part_d_by_rate_class : {};
  add(
    '## Source coverage',
    '',
    table(
      ['join', 'rows', 'share of all rows', 'notes'],
      [
        [
          'FDA NDC Directory identity (exact NDC)',
          formatCount(a.identity),
          pct(a.identity, n),
          `${countText(c.identity_ambiguous)} NDCs had conflicting FDA entries and were left without an identity`,
        ],
        [
          'FDA pharmacologic classes (`identity.pharm_classes`)',
          formatCount(a.pharmClasses.rows),
          pct(a.pharmClasses.rows, n),
          `${pct(a.pharmClasses.rows, a.identity)} of the rows with an identity; the others have none, because FDA’s \`PHARM_CLASSES\` cell is blank or its product records disagree. ` +
            `${formatCount(a.pharmClasses.epcRows)} rows have an established pharmacologic class (\`[EPC]\`), ${plural(a.pharmClasses.epcClasses, 'class', 'classes')} in all; ` +
            `${formatCount(a.pharmClasses.productsWithEpc)} of ${plural(a.products, 'product')} have one and get a class page` +
            (hasOwn(c, 'identity_pharm_classes_ambiguous') ? `; ${countText(c.identity_pharm_classes_ambiguous)} NDCs had FDA product records whose classes disagree` : ''),
        ],
        [
          'Medicare Part D (by name)',
          formatCount(a.partD),
          pct(a.partD, n),
          `pointing at ${formatCount(a.partDNames)} Part D names; ${md(
            sortedReasons(c.part_d_by_basis).map(([k, v]) => `${countText(v)} to a name CMS writes as ${BASIS_LABEL[k] || k}`).join(', ') ||
              'basis not recorded',
          )}; ${md(sortedReasons(c.part_d_by_join).map(([k, v]) => `${countText(v)} matched ${JOIN_LABEL[k] || `by ${k}`}`).join(', ') || 'join path not recorded')}` +
            (isPlainObject(c.part_d_fda_by_product_code)
              ? `; ${countText(c.part_d_fda_by_product_code.rows)} rows with no FDA identity were matched using FDA’s record for their product code, and ${countText(
                  c.part_d_fda_by_product_code.matched,
                )} of them joined`
              : '') +
            (isPlainObject(c.part_d_route_from_product_code)
              ? `; for a name CMS marks with \`*\`, ${countText(c.part_d_route_from_product_code.rows)} of those rows took their route from that record, and ${countText(
                  c.part_d_route_from_product_code.joined,
                )} of them kept the Part D figure because of it (\`part_d.route_from\`)`
              : ''),
        ],
        ['Medicare Part B (exact NDC on the crosswalk)', formatCount(a.partB), pct(a.partB, n), `pointing at ${formatCount(a.partBCodes)} HCPCS codes`],
        [
          'Part B with the package unit reconciled to the NADAC unit',
          formatCount(a.partBReconciled),
          pct(a.partBReconciled, n),
          `${pct(a.partBReconciled, a.partB)} of the Part B rows; only these can be converted to a price per NADAC unit` +
            (isPlainObject(c.part_b_unit_reconciled_by)
              ? `. Reconciled by: ${md(
                  sortedReasons(c.part_b_unit_reconciled_by)
                    .map(([k, v]) => `${countText(v)} because ${hasOwn(PART_B_RECONCILED_BY, k) ? PART_B_RECONCILED_BY[k] : `${k} (no description yet)`}`)
                    .join('; '),
                )}. The other ${formatCount(a.partB - a.partBReconciled)} keep the crosswalk’s package size as a quantity with no unit`
              : ''),
        ],
      ],
    ),
    '',
    'Part D matches by the NADAC file’s “Classification for Rate Setting”, and for OTC rows:',
    '',
    table(
      ['class', 'rows', 'matched', 'share matched'],
      [
        ...Object.keys(rateClasses)
          .sort(cmp)
          .map((k) => [code(k), countText(rateClasses[k].rows), countText(rateClasses[k].matched), pct(rateClasses[k].matched, rateClasses[k].rows)]),
        ...(isPlainObject(c.part_d_otc)
          ? [['OTC (any class)', countText(c.part_d_otc.rows), countText(c.part_d_otc.matched), pct(c.part_d_otc.matched, c.part_d_otc.rows)]]
          : []),
      ],
    ),
    '',
  );

  // Reference coverage.
  const sp = a.spreads;
  const spreadRows = [
    ['Medicare Part D', ...PRICE_STATES.map((s) => formatCount(sp.part_d[s] || 0)), formatCount(a.extremeRows.part_d)],
    ['Medicare Part B', ...PRICE_STATES.map((s) => formatCount(sp.part_b[s] || 0)), formatCount(a.extremeRows.part_b)],
  ];
  const fallback = sortedReasons(a.partBFallback);
  add(
    '## Reference coverage',
    '',
    'The Medicare reference price each row gets from `referencePrice()`: Part D first, Part B when there is no usable ' +
      'Part D figure, otherwise none ([the rule](../methodology.html#reference-price)).',
    '',
    table(
      ['reference', 'rows', 'share of rows', 'products', 'share of products'],
      [
        ['Medicare Part D', formatCount(a.refRows.part_d), pct(a.refRows.part_d, n), formatCount(a.refProducts.part_d), pct(a.refProducts.part_d, a.products)],
        ['Medicare Part B', formatCount(a.refRows.part_b), pct(a.refRows.part_b, n), formatCount(a.refProducts.part_b), pct(a.refProducts.part_b, a.products)],
        ['none (the card says why)', formatCount(a.refRows.none), pct(a.refRows.none, n), formatCount(a.refProducts.none), pct(a.refProducts.none, a.products)],
      ],
    ),
    '',
    `A product counts under Part D when any of its NDCs has a Part D reference, else under Part B when any has a Part B one. ` +
      `${formatCount(a.alternates)} rows with a Part D reference also have a usable Part B figure, shown in the provenance panel.` +
      (fallback.length === 1
        ? ` ${plural(fallback[0][1], 'row')} use Part B although a Part D name matched, because ${md(FALLBACK_PHRASE[fallback[0][0]] || fallback[0][0])}.`
        : fallback.length > 1
        ? ` ${plural(sumValues(a.partBFallback), 'row')} use Part B although a Part D name matched: ` +
          fallback.map(([k, v]) => `${formatCount(v)} because ${md(FALLBACK_PHRASE[k] || k)}`).join('; ') +
          '.'
        : ''),
    '',
    'Spreads (reference per unit ÷ NADAC per unit) by state, one per row with a reference:',
    '',
    table(['reference', ...PRICE_STATES, `estimated at or beyond ${EXTREME_HIGH}× or ${EXTREME_LOW}× (carry the caveat)`], spreadRows),
    '',
    `Part B figures shown next to a Part D reference in the provenance panel: ${stateCounts(a.altSpreads)}.`,
    '',
    `Cost-plus estimates ([the rule](../methodology.html#cost-plus)), at each product’s starting quantity: ${formatCount(a.costPlus.products)} of ` +
      `${plural(a.products, 'product')} have one, always \`estimated\`.` +
      (sortedReasons(a.costPlus.missing).length ? ` The other ${formatCount(sumValues(a.costPlus.missing))} show “We don’t know yet”, with the reason:` : ''),
    '',
    ...(sortedReasons(a.costPlus.missing).length
      ? [table(['reason the card gives', 'products'], sortedReasons(a.costPlus.missing).map(([k, v]) => [md(k), formatCount(v)])), '']
      : []),
    'Rows with no reference, by why each Medicare figure is not usable:',
    '',
    sortedReasons(a.noneWhy).length
      ? table(
          ['Part D', 'Part B', 'rows', 'share of rows'],
          sortedReasons(a.noneWhy).map(([k, v]) => {
            const [d, b] = k.split('|');
            return [md(PART_D_SIDE[d] || d), md(PART_B_SIDE[b] || b), formatCount(v), pct(v, n)];
          }),
        )
      : 'None.',
    '',
  );

  // Unmatched reasons.
  const pdUnmatched = sumValues(c.part_d_unmatched);
  const pbUnmatched = sumValues(c.part_b_unmatched);
  add(
    '## Unmatched reasons',
    '',
    `Why a row has no Part D name (\`counts.part_d_unmatched\`, recorded by \`tools/build_drugs.py\`). These ` +
      `${formatCount(pdUnmatched)} rows and the ${formatCount(a.partD)} matched rows make ${formatCount(pdUnmatched + a.partD)}` +
      (pdUnmatched + a.partD === n ? `, every row.` : `; there are ${formatCount(n)} rows, so **${formatCount(Math.abs(n - pdUnmatched - a.partD))} rows are not accounted for**.`),
    '',
    reasonTable(c.part_d_unmatched, PART_D_UNMATCHED_REASONS, n),
    '',
    `Why a row has no Part B data (\`counts.part_b_unmatched\`). These ${formatCount(pbUnmatched)} rows and the ` +
      `${formatCount(a.partB)} joined rows make ${formatCount(pbUnmatched + a.partB)}` +
      (pbUnmatched + a.partB === n ? `, every row.` : `; there are ${formatCount(n)} rows, so **${formatCount(Math.abs(n - pbUnmatched - a.partB))} rows are not accounted for**.`),
    '',
    reasonTable(c.part_b_unmatched, PART_B_UNMATCHED_REASONS, n),
    '',
    `No FDA identity: ${formatCount(n - a.identity)} rows (${pct(n - a.identity, n)}), whose NDC is not in the FDA NDC ` +
      `Directory’s package file or whose FDA entries conflict.`,
    '',
  );

  // Dates.
  add(
    '## Dates',
    '',
    'Each source file, and its age on the day it was retrieved (the build reads no clock). Age is counted from the ' +
      'NADAC and FDA file date, the start of the Part B quarter and the end of the Part D data year ' +
      '([freshness](../methodology.html#freshness)).',
    '',
    table(
      ['source', 'file', 'sha256', 'period', 'as of', 'retrieved', 'age at retrieval', 'stale after'],
      a.ages.map(({ id, info, fresh }) => {
        const e = src[id] || {};
        const age = !info
          ? '**not in SOURCE_INFO**'
          : !fresh
          ? '**no retrieved date**'
          : fresh.age_days === null
          ? `**unknown**: ${md(fresh.message)}`
          : `${plural(fresh.age_days, 'day')} from ${AGE_FROM_LABEL[fresh.basis] || md(fresh.basis)} (${md(fresh.date)})${fresh.stale ? ', **stale**' : ''}`;
        return [
          code(id),
          code(e.source_file || 'not recorded'),
          typeof e.sha256 === 'string' ? code(e.sha256.slice(0, SHA_PREFIX)) : 'not recorded',
          e.period ? md(e.period) : 'none',
          md(e.as_of_date || 'not recorded'),
          md(e.retrieved_date || 'not recorded'),
          age,
          info ? plural(info.stale_after_days, 'day') : 'n/a',
        ];
      }),
    ),
    '',
    a.effectiveMin
      ? `NADAC effective dates on the rows run from ${md(a.effectiveMin)} to ${md(a.effectiveMax)}. A row’s effective date is the ` +
          `date its NADAC took effect; every row comes from the file as of ${md(nadac.as_of_date || 'an unknown date')}.`
      : 'No NADAC effective dates found.',
    '',
  );
  const missingInfo = Object.keys(SOURCE_INFO).filter((id) => !hasOwn(src, id));
  if (missingInfo.length) add(`**Sources in SOURCE_INFO with no entry in \`data/drugs.json\`:** ${missingInfo.map(code).join(', ')}.`, '');

  // Carried forward.
  add(
    '## Carried-forward NADAC rows',
    '',
    `${formatCount(a.carriedRows)} rows (${pct(a.carriedRows, n)}) in ${formatCount(a.carriedProducts)} products carry ` +
      `explanation code ${NADAC_CARRIED_FORWARD_CODES.map(code).join(' or ')}: their NADAC was carried forward from an earlier file ` +
      'rather than set by this cycle’s survey. They are kept and labelled, not dropped.',
    '',
    sortedReasons(a.carriedByCodes).length
      ? table(['explanation codes on the row', 'rows'], sortedReasons(a.carriedByCodes).map(([k, v]) => [md(k), formatCount(v)]))
      : 'None.',
    '',
    'All explanation codes in this file:',
    '',
    table(
      ['code', 'rows', 'meaning'],
      Object.keys({ ...NADAC_EXPLANATION_CODES, ...a.explanation })
        .sort((x, y) => Number(x) - Number(y) || cmp(x, y))
        .map((k) => [
          code(k),
          formatCount(a.explanation[k] || 0),
          hasOwn(NADAC_EXPLANATION_CODES, k) ? md(NADAC_EXPLANATION_CODES[k]) : '**not in the NADAC data dictionary**',
        ]),
    ),
    '',
  );

  // Outliers.
  const spreadTable = (list) =>
    table(
      ['product', 'NDC', 'reference', 'NADAC', 'reference price', 'spread', 'state'],
      list.map((x) => [
        md(x.product),
        code(ndcText(x.ndc)) + (x.ndcs > 1 ? `, 1 of ${formatCount(x.ndcs)} NDCs` : ''),
        KIND_LABEL[x.kind] || md(x.kind),
        md(usdText(x.nadac)),
        md(usdText(x.reference)),
        md(formatMultiple(x.spread.value)),
        md(x.spread.state) + (isExtreme(x.spread) ? ', with the caveat' : ''),
      ]),
    );
  add(
    '## Outliers',
    '',
    `CMS flags ${formatCount(a.outlierNames)} of the ${plural(a.partDNames, 'Part D name')} as outliers (the average is ` +
      `substantially affected by outlier records); ${plural(a.outlierRows, 'row')} point at them and do not use them as a ` +
      `reference. The flag is blank for ${plural(a.blankFlagNames, 'name')} (${plural(a.blankFlagRows, 'row')}); a blank flag ` +
      `counts as not flagged, so the figure is used, and its reason says the flag is blank. ${plural(a.multiRouteNames, 'name')} ` +
      `carry CMS’s \`*\`: the average spans several routes of administration. ${plural(a.multiRouteRows, 'row')} point at them. Under the multi-route rule ` +
      'only rows whose FDA route is the one the name’s rows share keep the figure: the route of the row’s FDA identity or, for an NDC ' +
      'the FDA NDC Directory does not list as a package of its own, the route of FDA’s accepted record for the same product (labeler and product code), ' +
      'which follows the route the identity rows choose and does not count toward choosing it' +
      (isPlainObject(c.part_d_route_from_product_code)
        ? `; ${plural(c.part_d_route_from_product_code.joined, 'row')} keep the figure on a route taken that way`
        : '') +
      '. The others are counted under the `multi_route_` reasons above.',
    '',
    `Estimated spreads at or above ${EXTREME_HIGH}× or at or below ${EXTREME_LOW}× carry the caveat that the two figures may ` +
      `not describe the same unit or product ([the rule](../methodology.html#extreme-gap)): ${plural(a.extremeRows.part_d + a.extremeRows.part_b, 'row')} ` +
      `in ${plural(a.extremeProducts, 'product')}. They are shown, not hidden, and the card leads with “${md(EXTREME_HEADLINE)}” ` +
      'instead of the spread’s sentence. The thresholds are tested on the unrounded ratio. The products with the highest and lowest ' +
      'spreads are listed for review, each with the NDC that gives its extreme.',
    '',
    `Highest ${formatCount(a.highest.length)}:`,
    '',
    a.highest.length ? spreadTable(a.highest) : 'No spreads.',
    '',
    `Lowest ${formatCount(a.lowest.length)}:`,
    '',
    a.lowest.length ? spreadTable(a.lowest) : 'No spreads.',
    '',
  );

  // Rejected.
  add(
    '## Rejected and duplicate rows',
    '',
    table(
      ['measure', 'rows'],
      [
        ['NADAC lines rejected by the builder (bad NDC, empty description, unknown unit, or a price that is not a positive number)', countText(c.rejected)],
        ['duplicate NDC lines in the NADAC week (the newest effective date is kept)', countText(c.duplicate_ndcs)],
        ['NDCs repeated in `data/drugs.json`', formatCount(a.repeatedNdcs)],
      ],
    ),
    '',
  );

  // Floors.
  add(
    '## Floors',
    '',
    'CI fails when a floor fails (`tests/quality.test.js`).',
    '',
    table(
      ['floor', 'result', 'detail'],
      a.floors.map((f) => [md(f.label), f.pass ? 'PASS' : '**FAIL**', md(f.detail)]),
    ),
    '',
  );

  return out.join('\n').replace(/\n+$/, '') + '\n';
}
